function Factory(type) {
  this.type = type
}
const ProxiedFactory = new Proxy(Factory, {
  apply(target, thisArg, args) {
    return new target(...args)
  }
})
const obj = ProxiedFactory("user")
return {
  type: obj.type,
  instanceof: obj instanceof Factory
}
